/* Z-Ts documentation site — vanilla JS, no build step, no dependency.
 *
 * Four small features, each degrading gracefully when JS is unavailable:
 *   1. theme toggle (persisted in localStorage, respects prefers-color-scheme)
 *   2. sidebar search over `window.ZTS_SEARCH` (generated by `zig build docs`)
 *   3. copy buttons on every <pre class="code">
 *   4. mobile sidebar toggle
 */
(function () {
  "use strict";

  var doc = document;
  var root = doc.documentElement;

  /* ------------------------------------------------------------ 1. theme */

  function applyTheme(theme) {
    root.dataset.theme = theme;
    try { localStorage.setItem("zts-theme", theme); } catch (e) { /* private mode */ }
  }

  var toggle = doc.querySelector("[data-theme-toggle]");
  if (toggle) {
    toggle.addEventListener("click", function () {
      applyTheme(root.dataset.theme === "dark" ? "light" : "dark");
    });
  }
  if (!root.dataset.theme) {
    var prefersDark = window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches;
    root.dataset.theme = prefersDark ? "dark" : "light";
  }

  /* ----------------------------------------------------------- 2. search */

  var input = doc.getElementById("search");
  var results = doc.getElementById("search-results");
  var index = window.ZTS_SEARCH || [];
  // Pages live at different depths (`docs/tasks/x.html`), so every search hit is resolved
  // against the site root the generator recorded on <body>.
  var siteRoot = doc.body.getAttribute("data-root") || "";

  function fold(text) { return (text || "").toLowerCase(); }

  function snippet(text, needle) {
    var at = fold(text).indexOf(needle);
    if (at < 0) return text.slice(0, 96) + (text.length > 96 ? "…" : "");
    var start = Math.max(0, at - 40);
    var out = text.slice(start, start + 130).replace(/\s+/g, " ");
    return (start > 0 ? "…" : "") + out + (start + 130 < text.length ? "…" : "");
  }

  function render(query) {
    var needle = fold(query.trim());
    results.textContent = "";
    if (needle.length < 1) { results.hidden = true; return; }

    var hits = [];
    for (var i = 0; i < index.length; i++) {
      var entry = index[i];
      var title = fold(entry.t);
      var body = fold(entry.x);
      var at = body.indexOf(needle);
      var score = title.indexOf(needle) >= 0 ? 0 : at >= 0 ? 1 : -1;
      if (score < 0) continue;
      hits.push({ entry: entry, score: score, at: at });
    }
    hits.sort(function (a, b) {
      if (a.score !== b.score) return a.score - b.score;
      return a.entry.t.length - b.entry.t.length;
    });

    if (hits.length === 0) {
      var empty = doc.createElement("li");
      empty.className = "empty";
      empty.textContent = "ヒットなし";
      results.appendChild(empty);
      results.hidden = false;
      return;
    }

    hits.slice(0, 20).forEach(function (hit) {
      var li = doc.createElement("li");
      var a = doc.createElement("a");
      a.href = siteRoot + hit.entry.u;
      a.textContent = hit.entry.t;
      var group = doc.createElement("span");
      group.className = "group";
      group.textContent = hit.entry.g + " · " + snippet(hit.entry.x, needle);
      a.appendChild(group);
      li.appendChild(a);
      results.appendChild(li);
    });
    results.hidden = false;
  }

  if (input && results) {
    input.addEventListener("input", function () { render(input.value); });
    input.addEventListener("focus", function () { if (input.value) render(input.value); });
    input.addEventListener("keydown", function (event) {
      if (event.key === "Escape") {
        input.value = "";
        render("");
        input.blur();
      } else if (event.key === "Enter") {
        var first = results.querySelector("a");
        if (first) window.location.href = first.getAttribute("href");
      } else if (event.key === "ArrowDown") {
        var next = results.querySelector("a");
        if (next) { event.preventDefault(); next.focus(); }
      }
    });
    // `/` focuses the search box, like every other docs site.
    doc.addEventListener("keydown", function (event) {
      var tag = (event.target.tagName || "").toLowerCase();
      if (event.key === "/" && tag !== "input" && tag !== "textarea") {
        event.preventDefault();
        input.focus();
      }
    });
  }

  /* ------------------------------------------------------ 3. copy buttons */

  doc.querySelectorAll("pre.code").forEach(function (pre) {
    var button = doc.createElement("button");
    button.type = "button";
    button.className = "copy";
    button.textContent = "copy";
    button.addEventListener("click", function () {
      var code = pre.querySelector("code");
      var text = code ? code.textContent : pre.textContent;
      function done() {
        button.textContent = "copied";
        button.classList.add("done");
        setTimeout(function () {
          button.textContent = "copy";
          button.classList.remove("done");
        }, 1400);
      }
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(done, function () { /* fall through */ });
      } else {
        var area = doc.createElement("textarea");
        area.value = text;
        doc.body.appendChild(area);
        area.select();
        try { doc.execCommand("copy"); done(); } catch (e) { /* ignore */ }
        doc.body.removeChild(area);
      }
    });
    pre.appendChild(button);
  });

  /* --------------------------------------------------------- 4. sidebar */

  var menu = doc.querySelector("[data-menu-toggle]");
  var sidebar = doc.querySelector(".sidebar");
  if (menu && sidebar) {
    menu.addEventListener("click", function () { sidebar.classList.toggle("open"); });
    sidebar.addEventListener("click", function (event) {
      if (event.target.tagName === "A") sidebar.classList.remove("open");
    });
  }
})();
